const T={OPEN:['INVESTIGATING','MITIGATING','RESOLVED'],INVESTIGATING:['MITIGATING','RESOLVED'],MITIGATING:['MONITORING','RESOLVED'],MONITORING:['RESOLVED','MITIGATING'],RESOLVED:[]};export function newIncident({id,severity='SEV3',openedAt=Date.now(),summary}={}){if(!id)throw new Error('INCIDENT_ID_REQUIRED');return {id,severity,state:'OPEN',openedAt,summary,history:[{state:'OPEN',at:openedAt}]}}export function transitionIncident(i,state,{at=Date.now(),evidence=null}={}){if(!(T[i.state]||[]).includes(state))throw new Error('INVALID_INCIDENT_TRANSITION');return {...i,state,history:[...i.history,{state,at,evidence}],resolvedAt:state==='RESOLVED'?at:i.resolvedAt}}
